function initPlacePicker(v){let el=$('#placePicker');if(!el||typeof L==='undefined')return;if(window.placePickerMap){window.placePickerMap.remove();window.placePickerMap=null}let city=trip()?.cities?.[0],lat=Number(v.lat)||Number(city?.lat)||41.0082,lon=Number(v.lon)||Number(city?.lon)||28.9784,map=L.map(el).setView([lat,lon],v.lat&&v.lon?16:12);window.placePickerMap=map;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);let marker=v.lat&&v.lon?L.marker([lat,lon]).addTo(map):null;function setPin(a,b){if(marker)marker.setLatLng([a,b]);else marker=L.marker([a,b]).addTo(map);let form=el.closest('form');form.elements.lat.value=a.toFixed(6);form.elements.lon.value=b.toFixed(6)}map.on('click',e=>setPin(e.latlng.lat,e.latlng.lng));let form=el.closest('form');for(let field of [form.elements.lat,form.elements.lon])field.addEventListener('change',()=>{let a=Number(form.elements.lat.value),b=Number(form.elements.lon.value);if(form.elements.lat.value&&form.elements.lon.value&&Math.abs(a)<=90&&Math.abs(b)<=180){setPin(a,b);map.setView([a,b],16)}});setTimeout(()=>map.invalidateSize(),150)}
function hotelEditor(){let v=trip()?.hotel||{};modal(lang==='ar'?'تحديد الفندق وموقعه':'Set hotel and location',`<form>${input('name','name',v.name||$('#placeQuery')?.value||'','text',true)}${input('address','address',v.address||'')}<p class="muted">${lang==='ar'?'اضغط على مكان الفندق الصحيح بالخريطة قبل الحفظ.':'Tap the correct hotel on the map before saving.'}</p><div id="placePicker" class="place-picker"></div><div class="two-col"><label class="field">${lang==='ar'?'خط العرض':'Latitude'}<input type="number" name="lat" step="any" value="${esc(v.lat??'')}"></label><label class="field">${lang==='ar'?'خط الطول':'Longitude'}<input type="number" name="lon" step="any" value="${esc(v.lon??'')}"></label></div>${formButtons()}</form>`,d=>{let lat=Number(d.lat),lon=Number(d.lon);if(!d.lat||!d.lon||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw Error(lang==='ar'?'حدد موقع الفندق على الخريطة.':'Select the hotel location on the map.');trip().hotel={name:d.name.trim(),address:d.address.trim(),lat,lon,category:'hotel'}});setTimeout(()=>initPlacePicker(v),0)}
function parseGoogleLink(link){let lat=null,lon=null,m=link.match(/!3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/)||link.match(/(?:[?&](?:query|q|ll)=)(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/)||link.match(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/);if(m){lat=Number(m[1]);lon=Number(m[2])}let name='';try{let u=new URL(link);name=decodeURIComponent(u.pathname.match(/\/place\/([^/]+)/)?.[1]||u.searchParams.get('q')||u.searchParams.get('query')||'').replace(/\+/g,' ')}catch{}return{lat,lon,name,mapLink:link}}
function pasteMaps(){modal(t('pasteMap'),`<form>${input('link','mapLink','','url',true)}<p class="muted">${t('mapHelp')}</p>${formButtons()}</form>`,d=>{if(!/^https:\/\/(www\.)?(google\.[\w.]+\/maps|maps\.google\.[\w.]+|maps\.app\.goo\.gl)/i.test(d.mapLink))throw Error(t('badMap'));let v=parseGoogleLink(d.mapLink);if(finderMode==='hotel'){if(!v.lat||!v.lon)throw Error(lang==='ar'?'الرابط لا يتضمن إحداثيات الفندق؛ اختَر رابطًا يظهر موقعه على الخريطة.':'This link has no hotel coordinates; choose a map link with a visible location.');trip().hotel={name:v.name||$('#placeQuery')?.value||t('hotel'),address:'',lat:v.lat,lon:v.lon,mapLink:v.mapLink,category:'hotel'};return}setTimeout(()=>placeEditor(null,v),0)})}
function mapUrl(p){if(p.mapLink)return p.mapLink;let query=p.lat&&p.lon?`${p.lat},${p.lon}`:`${p.name}, ${p.address||trip()?.destination||''}`;return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(query)}
function googleDirections(stops){let q=p=>p.lat&&p.lon?`${p.lat},${p.lon}`:`${p.name}, ${p.address||trip().destination}`;if(stops.length<2)return '';return 'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(q(stops[0]))+'&destination='+encodeURIComponent(q(stops.at(-1)))+(stops.length>2?'&waypoints='+encodeURIComponent(stops.slice(1,-1).map(q).join('|')):'')+'&travelmode='+travelMode}
function routeGroups(stops){let origin=trip()?.hotel?.lat&&trip()?.hotel?.lon?trip().hotel:null,all=origin?[origin,...stops]:stops.slice(),groups=[];for(let i=0;i<all.length-1;i+=4)groups.push(all.slice(i,i+5));return groups}
function routeButtons(stops){return routeGroups(stops).map((g,i)=>`<button class="btn" data-action="dayRoute" data-part="${i}">${t('routePart')} ${i+1} ↗</button>`).join('')}
function navigationUrl(p){let destination=p.preferAddress?`${p.name}, ${p.address}`:p.lat&&p.lon?`${p.lat},${p.lon}`:`${p.name}, ${p.address||trip()?.destination||''}`;return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(destination)+'&travelmode='+travelMode}
function routeDay(part=0){let stops=trip().places.filter(p=>p.date===days(trip())[day]).sort((a,b)=>(a.order??0)-(b.order??0));let groups=routeGroups(stops),url=googleDirections(groups[part]||[]);if(url)openExternal(url)}
function openExternal(url){try{let u=new URL(url);if(u.protocol!=='https:')throw Error();window.location.assign(u.href)}catch{alert(t('invalidUrl'))}}
function details(p){modal(t('placeDetails'),`<div class="row"><h3>${esc(p.name)}</h3><span class="mini-tag">${esc((categories[p.category]||categories.other)[lang==='ar'?0:1])}</span></div><p class="muted">${esc(p.address||'')}</p>${photoGallery(p)}<p>${esc(p.note||'')}</p><div class="row"><button class="btn" data-action="placeHere" data-id="${p.id}">${t('openHere')}</button><button class="btn" data-action="placeNavigate" data-id="${p.id}">${t('navigate')} ↗</button><button class="btn" data-action="editPlace" data-id="${p.id}">${t('edit')}</button><button class="tiny danger" data-action="deletePlace" data-id="${p.id}">${t('delete')}</button></div><h3>${t('comments')} (${(p.comments||[]).length})</h3><div>${(p.comments||[]).map(c=>`<div class="comment">${esc(c.text)}<br><small class="muted">${fmt(c.date)}</small><button class="tiny danger" data-action="deleteComment" data-id="${p.id}" data-comment="${c.id}">×</button></div>`).join('')||`<p class="muted">${t('noComments')}</p>`}</div><form id="commentForm">${textarea('addComment','text','')}<button class="btn primary full" type="submit">+ ${t('addComment')}</button></form>`,null);$('#commentForm').onsubmit=e=>{e.preventDefault();let text=new FormData(e.target).get('text')?.trim();if(!text)return;p.comments??=[];p.comments.push({id:id(),text,date:new Date().toISOString().slice(0,10)});persist();details(p)}}
function expenseEditor(v){modal(v?t('edit'):t('addExpense'),`<form>${input('description','name',v?.name||'', 'text',true)}${input('amount','amount',v?.amount||'', 'number',true)}<label class="field">${t('category')}${opt(expenseCategories,v?.category||'other')}</label>${input('date','date',v?.date||new Date().toISOString().slice(0,10),'date')}<div class="two-col"><label class="field">${t('paidBy')}<select name="paidBy"><option value="">—</option>${personNames().map(n=>`<option value="${esc(n)}" ${v?.paidBy===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label>${input('forPeople','splitCount',v?.splitCount||Math.max(1,personNames().length),'number')}</div>${formButtons()}${v?`<button type="button" class="btn danger" data-action="deleteExpense" data-id="${v.id}">${t('delete')}</button>`:''}</form>`,d=>{let amount=Number(d.amount);if(!Number.isFinite(amount)||amount<0)throw Error(t('badAmount'));let obj={name:d.name.trim(),amount,category:d.category,date:d.date,paidBy:d.paidBy,splitCount:Math.max(1,Number(d.splitCount)||1)};if(v)Object.assign(v,obj);else(trip().expenses??=[]).push({id:id(),...obj})})}
function taskEditor(){modal(t('addTask'),`<form>${input('addTask','text','','text',true)}${formButtons()}</form>`,d=>{(trip().tasks??=[]).push({id:id(),text:d.text.trim(),done:false})})}
function settings(){modal(t('settings'),`<div class="panel"><h3>${t('language')}</h3><button class="btn" data-action="toggleLanguage">${lang==='ar'?'English':'العربية'}</button></div><div class="panel"><h3>${t('backup')}</h3><button class="btn" data-action="import">↑ ${t('import')}</button>${trip()?`<button class="btn" data-action="export">↓ ${t('export')}</button>`:''}<p class="muted">${t('dataInfo')}</p></div>`,null)}
function renderLists(x){let lists=x.lists||[];return `<div class="section-title"><h2>${t('lists')}</h2><button class="btn primary" data-action="newList">+ ${t('newList')}</button></div>${lists.map(l=>`<section class="panel"><div class="row"><h3>${esc(l.title)} <small class="muted">(${x.places.filter(p=>p.listId===l.id).length})</small></h3><div><button class="tiny" data-action="editList" data-id="${l.id}">✎</button><button class="tiny danger" data-action="deleteList" data-id="${l.id}">×</button></div></div>${x.places.filter(p=>p.listId===l.id).map(p=>placeCard(p,false)).join('')||`<p class="muted">${t('noPlaces')}</p>`}<button class="btn subtle" data-action="addPlace" data-list="${l.id}">+ ${t('addPlace')}</button></section>`).join('')}<section class="panel"><h3>${t('unlisted')}</h3>${x.places.filter(p=>!p.listId).map(p=>placeCard(p,false)).join('')||`<p class="muted">${t('noLists')}</p>`}<button class="btn" data-action="addPlace">+ ${t('addPlace')}</button></section>`}
function listEditor(l){modal(l?t('edit'):t('newList'),`<form>${input('listName','title',l?.title||'','text',true)}${formButtons()}</form>`,d=>{let title=d.title.trim();if(!title)return;if(l)l.title=title;else(trip().lists??=[]).push({id:id(),title})})}
const bookingTypes={flight:'bookFlight',hotel:'bookHotel',car:'bookCar',activity:'bookActivity'};
function renderBookings(x){return `<div class="section-title"><h2>${t('bookings')}</h2><button class="btn primary" data-action="newBooking">+ ${t('addBooking')}</button></div><div class="panel">${(x.bookings||[]).length?x.bookings.map(v=>`<div class="place-card"><div class="place-thumb place-fallback">${{flight:'✈',hotel:'⌂',car:'🚘',activity:'🎟'}[v.type]||'📄'}</div><div class="place-info"><span class="mini-tag">${t(bookingTypes[v.type]||'bookings')}</span><h3>${esc(v.name)}</h3><p>${esc(v.provider||'')} · ${fmt(v.start)} ${v.end?'– '+fmt(v.end):''}</p><p>${t('confirmation')}: ${esc(v.confirmation||'—')}</p><div class="place-actions"><button class="tiny" data-action="editBooking" data-id="${v.id}">${t('edit')}</button>${safeBookingLink(v.link)?`<a class="tiny" href="${esc(safeBookingLink(v.link))}" target="_blank" rel="noopener noreferrer">${t('bookingLink')} ↗</a>`:''}${v.attachment?`<button class="tiny" data-action="downloadBooking" data-id="${v.id}">↓ ${t('attachment')}</button>`:''}<button class="tiny danger" data-action="deleteBooking" data-id="${v.id}">${t('delete')}</button></div></div></div>`).join(''):`<div class="empty"><div class="symbol">✈</div>${t('noBookings')}</div>`}</div>`}
function fileData(file){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error(t('photoRead')));r.readAsDataURL(file)})}
function safeBookingLink(link){try{let u=new URL(link);return u.protocol==='https:'?u.href:''}catch{return ''}}
function bookingEditor(v){modal(v?t('edit'):t('addBooking'),`<form><label class="field">${t('category')}<select name="type">${Object.entries(bookingTypes).map(([key,label])=>`<option value="${key}" ${v?.type===key?'selected':''}>${t(label)}</option>`).join('')}</select></label>${input('name','name',v?.name||'','text',true)}${input('provider','provider',v?.provider||'')}${input('confirmation','confirmation',v?.confirmation||'')}<div class="two-col">${input('departure','start',v?.start||'','date')}${input('arrival','end',v?.end||'','date')}</div>${input('link','link',v?.link||'','url')}${textarea('note','note',v?.note||'')}<label class="field">${t('attachment')}<input name="attachmentFile" type="file" accept="image/*,application/pdf"><small>${lang==='ar'?'صورة أو PDF حتى 2MB':'Image or PDF up to 2MB'}</small></label>${formButtons()}</form>`,async d=>{let attachment=v?.attachment||null,filename=v?.filename||'';if(d.attachmentFile?.size){if(d.attachmentFile.size>2e6)throw Error(lang==='ar'?'المرفق أكبر من 2MB':'Attachment exceeds 2MB');attachment=await fileData(d.attachmentFile);filename=d.attachmentFile.name}if(d.link&&!safeBookingLink(d.link))throw Error(t('invalidUrl'));let obj={type:d.type,name:d.name.trim(),provider:d.provider,confirmation:d.confirmation,start:d.start,end:d.end,link:d.link,note:d.note,attachment,filename};if(v)Object.assign(v,obj);else(trip().bookings??=[]).push({id:id(),...obj})})}
function focusMap(lat,lon){tab='mapView';mapFilter='all';mapPreview=true;render();setTimeout(()=>mapInstance?.setView([Number(lat),Number(lon)],15),350)}
function setMapTiles(){if(!mapInstance)return;if(mapTiles)mapInstance.removeLayer(mapTiles);if(mapMode==='satellite'){mapTiles=L.tileLayer('https://tiles.versatiles.org/tiles/satellite/{z}/{x}/{y}',{tileSize:512,zoomOffset:-1,maxNativeZoom:13,maxZoom:19,attribution:'<a href="https://versatiles.org/sources/">© VersaTiles imagery sources</a>'});mapTiles.on('tileerror',()=>{if(mapMode==='satellite'){mapMode='street';localStorage.setItem('rahlati-map-mode','street');setMapTiles();let b=$('.map-style-switch');if(b)b.textContent=lang==='ar'?'◈ القمر الصناعي':'◈ Satellite'}})}else mapTiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'});mapTiles.addTo(mapInstance)}
function initMap(){let el=$('#interactiveMap'),x=trip();if(!el||!x)return;if(typeof L==='undefined'){el.innerHTML='<p class="muted">'+t('noMap')+'</p>';return}let shown=x.places.filter(p=>p.lat&&p.lon&&(mapFilter==='all'||p.date===mapFilter));mapInstance=L.map(el,{zoomControl:true});setMapTiles();let bounds=[],hotel=x.hotel;if(hotel?.lat&&hotel?.lon){let c=[Number(hotel.lat),Number(hotel.lon)];bounds.push(c);L.marker(c,{icon:L.divIcon({className:'hotel-pin',html:'⌂',iconSize:[34,34],iconAnchor:[17,17]})}).addTo(mapInstance).bindPopup(`<strong>⌂ ${esc(hotel.name)}</strong><br>${esc(hotel.address||'')}<br><button class="tiny" data-action="hotelMap">${t('navigate')} ↗</button>`)}let ordered=shown.slice().sort((a,b)=>String(a.date||'9999').localeCompare(String(b.date||'9999'))||(a.order??0)-(b.order??0));ordered.forEach((p,i)=>{let coord=[Number(p.lat),Number(p.lon)];bounds.push(coord);let marker=L.marker(coord,{icon:L.divIcon({className:'custom-pin',html:`<span>${i+1}</span>`,iconSize:[30,36],iconAnchor:[15,36]})}).addTo(mapInstance);marker.bindPopup(`<strong>${i+1}. ${esc(p.name)}</strong><br>${esc(p.address||'')}<br><button class="tiny" data-action="placeDetails" data-id="${p.id}">${t('placeDetails')}</button>`)});if(mapFilter!=='all'){let dayStops=ordered.filter(p=>p.date===mapFilter);let track=[...(hotel?.lat&&hotel?.lon?[[hotel.lat,hotel.lon]]:[]),...dayStops.map(p=>[p.lat,p.lon])];if(track.length>1)L.polyline(track,{color:'#d36a4b',weight:4,dashArray:'8,6'}).addTo(mapInstance)}if(activeLocation){let c=[activeLocation.lat,activeLocation.lon];L.circleMarker(c,{radius:9,color:'#167bc9',fillOpacity:.9}).addTo(mapInstance).bindPopup(t('locationNow'));bounds.push(c)}if(bounds.length)mapInstance.fitBounds(bounds,{padding:[42,42],maxZoom:14});else mapInstance.setView([41.0082,28.9784],11);setTimeout(()=>{if(mapInstance){mapInstance.invalidateSize();if(bounds.length)mapInstance.fitBounds(bounds,{padding:[42,42],maxZoom:14})}},250)}
function distanceKm(a,b){if(!a.lat||!a.lon||!b.lat||!b.lon)return null;let rad=Math.PI/180,dLat=(b.lat-a.lat)*rad,dLon=(b.lon-a.lon)*rad,h=Math.sin(dLat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dLon/2)**2;return 6371*2*Math.asin(Math.sqrt(h))}
function leg(a,b){let km=distanceKm(a,b);if(km==null)return '';let mins=Math.max(1,Math.round(km/(travelMode==='walking'?4.5:travelMode==='transit'?18:28)*60));return `<div class="leg">${t('estimate')}: ${km.toFixed(1)} km · ~${mins} ${lang==='ar'?'دقيقة':'min'} <button class="tiny" data-action="legDirections" data-from="${a.id}" data-to="${b.id}">${t('directions')} ↗</button></div>`}
function optimizeDay(){let x=trip(),items=x.places.filter(p=>p.date===days(x)[day]).sort((a,b)=>(a.order??0)-(b.order??0));if(items.length<3||items.some(p=>!p.lat||!p.lon))return alert(lang==='ar'?'لازم 3 أماكن على الأقل مع مواقع محددة.':'Add at least 3 places with coordinates.');x.undoOrder=items.map(v=>({id:v.id,order:v.order}));let result=[items.shift()];while(items.length){let last=result[result.length-1],i=items.reduce((best,p,j)=>distanceKm(last,p)<distanceKm(last,items[best])?j:best,0);result.push(items.splice(i,1)[0])}result.forEach((p,i)=>p.order=i);persist();render()}
function undoOrder(){let x=trip();if(!x.undoOrder)return;x.undoOrder.forEach(v=>{let p=x.places.find(z=>z.id===v.id);if(p)p.order=v.order});delete x.undoOrder;persist();render()}
function personNames(){return String(trip()?.travelers||'').split(/[,،\n]/).map(s=>s.trim()).filter(Boolean)}

function planByArea(requestedDays){let x=trip(),places=x.places.filter(p=>p.lat&&p.lon),missing=x.places.filter(p=>!p.lat||!p.lon);if(!places.length)return alert(t('needGeocoded'));let dateList=days(x),maximum=Math.min(dateList.length,places.length),k=Math.min(maximum,Number(requestedDays)||Math.ceil(places.length/3));if(!k)return;let hotel=x.hotel,metric=(a,b)=>distanceKm(a,b)??1e6,seed=hotel?.lat&&hotel?.lon?hotel:places[0];let centers=[places.reduce((best,p)=>metric(seed,p)<metric(seed,best)?p:best,places[0])];while(centers.length<k){let choice=places.filter(p=>!centers.includes(p)).reduce((best,p)=>Math.min(...centers.map(c=>metric(p,c)))>Math.min(...centers.map(c=>metric(best,c)))?p:best,places.find(p=>!centers.includes(p)));centers.push(choice)}let groups=Array.from({length:k},()=>[]),size=Math.ceil(places.length/k);places.slice().sort((a,b)=>Math.min(...centers.map(c=>metric(b,c)))-Math.min(...centers.map(c=>metric(a,c)))).forEach(p=>{let ix=centers.map((c,i)=>({i,d:metric(p,c)})).sort((a,b)=>a.d-b.d).find(v=>groups[v.i].length<size)?.i??groups.findIndex(g=>g.length<size);groups[ix].push(p)});groups=groups.sort((a,b)=>metric(seed,a[0])-metric(seed,b[0]));groups=groups.map(g=>{let left=g.slice(),out=[],from=seed;while(left.length){let ix=left.reduce((best,p,j)=>metric(from,p)<metric(from,left[best])?j:best,0);from=left.splice(ix,1)[0];out.push(from)}return out});let preview=groups.map((g,i)=>`<div class="plan-day"><strong>${t('day')} ${i+1} · ${fmt(dateList[i])}</strong><p>${g.map((p,j)=>`${j+1}. ${esc(p.name)} <small>(${esc((categories[p.category]||categories.other)[lang==='ar'?0:1])})</small>`).join(' ← ')}</p></div>`).join('');modal(t('planPreview'),`<p>${t('autoPlanHint')}</p><label class="field">${t('planDays')}<select id="planDays">${dateList.slice(0,maximum).map((_,i)=>`<option value="${i+1}" ${k===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label>${preview}${missing.length?`<p class="muted">${missing.length} ${t('needGeocoded')}</p>`:''}<button class="btn primary full" data-action="applyPlan">${t('applyPlan')}</button>`,null);window.pendingPlan={tripId:x.id,groups,dateList}}
function applyPlan(){let x=trip(),p=window.pendingPlan;if(!p||p.tripId!==x.id)return;x.undoPlan=x.places.map(v=>({id:v.id,date:v.date,order:v.order,time:v.time}));p.groups.forEach((g,i)=>g.forEach((v,j)=>{let currentPlace=x.places.find(z=>z.id===v.id);if(currentPlace){currentPlace.date=p.dateList[i];currentPlace.order=j}}));delete window.pendingPlan;close();persist();tab='itinerary';day=0;render()}
function undoPlan(){let x=trip();if(!x?.undoPlan)return;x.undoPlan.forEach(v=>{let p=x.places.find(z=>z.id===v.id);if(p){p.date=v.date;p.order=v.order;p.time=v.time}});delete x.undoPlan;persist();render()}
function scheduleDay(){let x=trip(),list=x.places.filter(p=>p.date===days(x)[day]).sort((a,b)=>(a.order??0)-(b.order??0));if(!list.length)return;let cursor=9*60;list.forEach((p,i)=>{if(p.time){let [h,m]=p.time.split(':').map(Number);if(Number.isFinite(h)&&Number.isFinite(m))cursor=h*60+m}else{let hh=Math.floor(cursor/60)%24,mm=cursor%60;p.time=String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0')}let next=list[i+1],travel=next&&distanceKm(p,next);cursor+=Math.max(15,Number(p.duration)||(['food','cafe'].includes(p.category)?75:90))+Math.max(15,travel?Math.ceil(travel/(travelMode==='walking'?4.5:25)*60):20);cursor=Math.min(cursor,23*60+45)});persist();render()}
function exportKml(){let x=trip();if(!x?.places?.some(p=>p.lat!=null&&p.lon!=null)&&!(x?.hotel?.lat!=null&&x?.hotel?.lon!=null))return alert(t('needGeocoded'));let escapeXml=v=>String(v??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&quot;',"'":'&apos;'}[c]));let point=(p,label)=>`<Placemark><name>${escapeXml(label)}</name><description>${escapeXml([p.address,p.note].filter(Boolean).join(' · '))}</description><Point><coordinates>${Number(p.lon)},${Number(p.lat)},0</coordinates></Point></Placemark>`;let groups=days(x).map((d,i)=>({title:`${t('day')} ${i+1} · ${d}`,places:x.places.filter(p=>p.date===d&&Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lon))&&p.lat!=null&&p.lon!=null).sort((a,b)=>(a.order??0)-(b.order??0))}));let spare=x.places.filter(p=>!days(x).includes(p.date)&&p.lat!=null&&p.lon!=null);if(spare.length)groups.push({title:t('undated'),places:spare});let folders=groups.filter(g=>g.places.length).map(g=>`<Folder><name>${escapeXml(g.title)}</name>${g.places.map((p,i)=>point(p,`${i+1}. ${p.name}`)).join('')}</Folder>`).join('');let hotel=x.hotel?.lat!=null&&x.hotel?.lon!=null?`<Folder><name>${escapeXml(t('hotel'))}</name>${point(x.hotel,x.hotel.name)}</Folder>`:'';let xml=`<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>${escapeXml(x.title)}</name>${hotel}${folders}</Document></kml>`,filename='rahlati-'+(x.start||'trip')+'.kml';saveFile(filename,'application/vnd.google-earth.kml+xml',xml);modal(t('exportGoogle'),`<p>${t('exportHint')}</p><a class="btn primary full" href="https://www.google.com/mymaps" target="_blank" rel="noopener">Google My Maps ↗</a>`,null)}
function locateMe(){if(!navigator.geolocation)return alert(t('locationDenied'));navigator.geolocation.getCurrentPosition(pos=>{activeLocation={lat:pos.coords.latitude,lon:pos.coords.longitude};if(tab!=='mapView')tab='mapView';render();setTimeout(()=>mapInstance?.setView([activeLocation.lat,activeLocation.lon],15),350)},()=>alert(t('locationDenied')),{enableHighAccuracy:true,timeout:15000})}
async function shareTrip(){let x=trip();if(!x)return;let file=new File([JSON.stringify({format:'rahlati-v2',trip:x})],`rahlati-${x.start||'trip'}.json`,{type:'application/json'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({title:x.title,files:[file]});return}catch(error){if(error.name==='AbortError')return}}exportTrip()}
function saveFile(name,mime,content){if(window.RahlatiAndroid?.save){window.RahlatiAndroid.save(name,mime,btoa(unescape(encodeURIComponent(content))));return}let u=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),4000)}
function exportTrip(){let x=trip();if(!x)return;saveFile(`rahlati-${x.start||'trip'}.json`,'application/json',JSON.stringify({format:'rahlati-v2',trip:x},null,2))}
function move(p,dir){let list=trip().places.filter(v=>v.date===p.date).sort((a,b)=>(a.order??0)-(b.order??0)),i=list.findIndex(v=>v.id===p.id),j=i+dir;if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];list.forEach((v,n)=>v.order=n);persist();render()}
document.addEventListener('click',async e=>{let b=e.target.closest('button,[data-close]');if(!b)return;if(b.hasAttribute('data-close')){close();return}let a=b.dataset.action;if(a==='pickCity'){let name=b.dataset.name,lat=Number(b.dataset.lat),lon=Number(b.dataset.lon);if(name&&Number.isFinite(lat)&&Number.isFinite(lon)&&!editingCities.some(v=>v.name===name)){editingCities.push({name,lat,lon});cityLabels();cityChoices($('#tripCountry')?.value);$('#cityQuery').value=''}return}if(a==='removeCity'){editingCities.splice(Number(b.dataset.index),1);cityLabels();cityChoices($('#tripCountry')?.value);return}if(b.id==='homeBtn'||a==='home'){current='';persist();render();return}if(b.id==='langBtn'||a==='toggleLanguage'){lang=lang==='ar'?'en':'ar';localStorage.setItem('rahlati-lang',lang);close();render();return}if(b.id==='settingsBtn'){settings();return}if(b.dataset.nav){if(b.dataset.nav==='trips')current='';else if(trip())tab=b.dataset.nav;persist();render();return}if(b.dataset.tab){tab=b.dataset.tab;render();return}if(b.dataset.day!==undefined){day=Number(b.dataset.day);render();return}let x=trip(),p=x?.places?.find(z=>z.id===b.dataset.id);switch(a){case'newTrip':tripEditor();break;case'openTrip':current=b.dataset.id;tab='itinerary';day=0;persist();render();break;case'editTrip':tripEditor(x);break;case'deleteTrip':if(confirm(t('deleteConfirm'))){trips=trips.filter(v=>v.id!==b.dataset.id);persist();render()}break;case'addPlace':targetListId=b.dataset.list||'';placeFinder();break;case'setHotel':placeFinder('hotel');break;case'searchPlace':searchPlaces();break;case'expandedSearch':expandedSearch();break;case'googleSearch':openExternal('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent([$('#placeQuery')?.value,trip()?.destination].filter(Boolean).join(', ')));break;case'dayRoute':routeDay(Number(b.dataset.part||0));break;case'autoPlan':planByArea();break;case'showPlaces':tab='places';render();break;case'mapDay':mapFilter=days(x)[day];tab='mapView';render();break;case'undoPlan':undoPlan();break;case'scheduleDay':scheduleDay();break;case'toggleVisited':if(p){p.visited=!p.visited;persist();render()}break;case'applyPlan':applyPlan();break;case'exportKml':exportKml();break;case'hotelHere':focusMap(x.hotel.lat,x.hotel.lon);break;case'hotelMap':openExternal(navigationUrl(x.hotel));break;case'locateMe':locateMe();break;case'toggleMapPreview':mapPreview=!mapPreview;render();break;case'googleDayRoute':{let stops=x.places.filter(p=>p.date===b.dataset.date&&p.lat&&p.lon).sort((a,z)=>(a.order??0)-(z.order??0)),url=googleDirections(routeGroups(stops)[Number(b.dataset.part)]||[]);if(url)openExternal(url);break}case'mapStyle':mapMode=mapMode==='satellite'?'street':'satellite';localStorage.setItem('rahlati-map-mode',mapMode);setMapTiles();b.textContent=mapMode==='satellite'?(lang==='ar'?'🗺 الخريطة العادية':'🗺 Street map'):(lang==='ar'?'◈ القمر الصناعي':'◈ Satellite');break;case'selectResult':chooseSuggestion(Number(b.dataset.index));break;case'manualPlace':placeEditor();break;case'manualHotel':hotelEditor();break;case'pasteMap':pasteMaps();break;case'placeDetails':details(p);break;case'findPublicPhotos':if(p)findPublicPhotos(p);break;case'choosePublicPhoto':{let photo=suggestedPhotos[Number(b.dataset.index)];if(p&&photo){p.photos=placePhotos(p);if(!p.photos.includes(photo.url))p.photos.push(photo.url);p.photo=photo.url;p.photoCredits=(p.photoCredits||[]).filter(c=>c.url!==photo.url).concat(photo);persist();details(p)}break}case'chooseCover':if(p){let photos=placePhotos(p),index=Number(b.dataset.index);if(photos[index]){p.photo=photos[index];persist();details(p);render()}}break;case'placePhotosMap':if(p)openExternal(mapUrl(p));break;case'editPlace':placeEditor(p);break;case'deletePlace':if(confirm(t('deleteConfirm'))){x.places=x.places.filter(v=>v.id!==p.id);close();persist();render()}break;case'placeMap':openExternal(mapUrl(p));break;case'placeHere':if(p?.lat&&p?.lon){close();focusMap(p.lat,p.lon)}else openExternal(mapUrl(p));break;case'placeNavigate':openExternal(navigationUrl(p));break;case'openMap':{let center=x.hotel?.lat&&x.hotel?.lon?x.hotel:(x.cities||[])[0];openExternal(center?.lat&&center?.lon?'https://www.google.com/maps/@?api=1&map_action=map&center='+encodeURIComponent(center.lat+','+center.lon)+'&zoom=15&basemap=satellite':'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(b.dataset.query||x.destination));break}case'movePlace':move(p,Number(b.dataset.direction));break;case'deleteComment':p.comments=p.comments.filter(c=>c.id!==b.dataset.comment);persist();details(p);break;case'addExpense':expenseEditor();break;case'editExpense':expenseEditor(x.expenses.find(v=>v.id===b.dataset.id));break;case'deleteExpense':if(confirm(t('deleteConfirm'))){x.expenses=x.expenses.filter(v=>v.id!==b.dataset.id);close();persist();render()}break;case'addTask':taskEditor();break;case'deleteTask':x.tasks=x.tasks.filter(v=>v.id!==b.dataset.id);persist();render();break;case'newList':listEditor();break;case'editList':listEditor(x.lists.find(v=>v.id===b.dataset.id));break;case'deleteList':if(confirm(t('deleteConfirm'))){x.places.filter(p=>p.listId===b.dataset.id).forEach(p=>p.listId='');x.lists=x.lists.filter(v=>v.id!==b.dataset.id);persist();render()}break;case'newBooking':bookingEditor();break;case'editBooking':bookingEditor(x.bookings.find(v=>v.id===b.dataset.id));break;case'deleteBooking':if(confirm(t('deleteConfirm'))){x.bookings=x.bookings.filter(v=>v.id!==b.dataset.id);persist();render()}break;case'downloadBooking':{let v=x.bookings.find(z=>z.id===b.dataset.id),a=document.createElement('a');a.href=v.attachment;a.download=v.filename||'booking';a.click();break}case'mode':travelMode=b.dataset.mode;render();break;case'optimize':optimizeDay();break;case'undoOrder':undoOrder();break;case'legDirections':{let a=x.places.find(v=>v.id===b.dataset.from),z=x.places.find(v=>v.id===b.dataset.to);openExternal('https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(a.lat&&a.lon?`${a.lat},${a.lon}`:a.name)+'&destination='+encodeURIComponent(z.lat&&z.lon?`${z.lat},${z.lon}`:z.name)+'&travelmode='+travelMode);break}case'share':shareTrip();break;case'export':exportTrip();break;case'import':$('#backupInput').click();break}}
);
document.addEventListener('input',e=>{if(e.target.id==='cityQuery'){clearTimeout(citySearchTimer);citySearchTimer=setTimeout(findCities,300)}});
document.addEventListener('change',e=>{if(e.target.id==='tripCountry'){editingCities=[];cityLabels();cityChoices(e.target.value);return}if(e.target.id==='mapFilter'){mapFilter=e.target.value;render();return}if(e.target.id==='planDays'){planByArea(Number(e.target.value));return}if(e.target.dataset.task){let v=trip()?.tasks?.find(z=>z.id===e.target.dataset.task);if(v){v.done=e.target.checked;persist();render()}}});document.addEventListener('input',e=>{if(e.target.id==='placeQuery')suggestPlaces();if(e.target.id==='tripNotes'){trip().notes=e.target.value;persist()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').classList.contains('hidden'))close();if(e.target.id==='placeQuery'&&e.key==='ArrowDown'&&searchResults.length){e.preventDefault();$('#placeResults .search-result')?.focus()}if(e.key==='Enter'&&e.target.id==='placeQuery'){e.preventDefault();if(searchResults.length)chooseSuggestion(0);else searchPlaces()}if(e.target.matches('.search-result')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();let items=[...document.querySelectorAll('#placeResults .search-result')],next=items.indexOf(e.target)+(e.key==='ArrowDown'?1:-1);(items[next]||$('#placeQuery'))?.focus()}});
$('#backupInput').addEventListener('change',async e=>{let f=e.target.files?.[0];if(!f)return;try{let d=JSON.parse(await f.text()),x=d.trip;if(!['rahlati-v1','rahlati-v2'].includes(d.format)||!x||typeof x.title!=='string'||!Array.isArray(x.places)||!Array.isArray(x.expenses))throw Error(t('badFile'));x.id=id();x.places=x.places.map(v=>({...v,id:id(),comments:v.comments||[]}));x.expenses=x.expenses.map(v=>({...v,id:id()}));x.tasks=x.tasks||[];x.lists=x.lists||[];x.bookings=x.bookings||[];trips.unshift(x);current=x.id;tab='itinerary';close();persist();render();alert(t('imported'))}catch(err){alert(err.message)}e.target.value=''});
